import { test, expect, type Page, type Request } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/company_6.json') });

// UI texts (he): the product string has a comma — «יש להזין סכום בשקלים שלמים, גדול מ-0».
const AMOUNT_ERR = /יש להזין סכום בשקלים שלמים,? גדול מ-0/;
const MAX_ERR = /הסכום המרבי הוא ₪\s?9,999,999/;
const SENT = 'ההצעה שלכם נשלחה';
const INVALID_LOW = ['-50', '0', '12.5', '1.5', 'abc'];
const INVALID_HIGH = ['999999999', '1000000000000'];

/** Walks /tenders pages and returns the first tender whose details show an empty offer form for this HR. */
async function findTenderWithOfferForm(page: Page): Promise<string | null> {
  const hrefs: string[] = [];
  await page.goto('/tenders');
  const count = page.getByText(/^\d+ תוצאות$/);
  await expect(count).toBeVisible();
  const total = Number((await count.innerText()).match(/\d+/)![0]);
  for (let p = 1; hrefs.length < total && p <= 20; p++) {
    if (p > 1) await page.goto(`/tenders?page=${p}`);
    const cards = page.getByRole('link', { name: /^לפרטי המכרז/ });
    await expect(cards.first()).toBeVisible();
    const pageHrefs = await cards.evaluateAll((els) => els.map((e) => e.getAttribute('href') ?? ''));
    const fresh = pageHrefs.filter((h) => h && !hrefs.includes(h));
    if (fresh.length === 0) break;
    hrefs.push(...fresh);
  }
  for (const href of hrefs) {
    await page.goto(href);
    const side = page.getByRole('dialog').getByRole('complementary');
    // Either the candidacy list, the offer form or an existing offer block is rendered.
    await expect(side.getByRole('heading', { level: 3 })).toBeVisible();
    const amount = side.getByRole('textbox', { name: /ההצעה שלי \(/ }).or(side.getByLabel(/ההצעה שלי \(/));
    if (await amount.first().isVisible()) return href;
  }
  return null;
}

test.describe('Offer amount validation and own offer management (#1004e9)', () => {
  test('Offer form rejects invalid amounts and sends nothing @desktop @prod-safe #1004e9', async ({ page }) => {
    test.setTimeout(240_000);

    // 1. Open /tenders → a foreign open tender where this HR has no offer yet
    const href = await findTenderWithOfferForm(page);
    test.skip(
      !href,
      'No open tender with an empty «הגשת הצעה למכרז» form for company_6 — every offer-type tender already has an offer from this HR. ' +
        'Needs a fresh QA-AUTO offer tender from the company role (see plan 1.2).',
    );

    const side = page.getByRole('dialog').getByRole('complementary');
    await expect(side.getByRole('heading', { name: 'הגשת הצעה למכרז' })).toBeVisible();
    const amount = side.getByRole('textbox', { name: /ההצעה שלי \(/ }).or(side.getByLabel(/ההצעה שלי \(/)).first();
    const submit = side.getByRole('button', { name: 'הגשת הצעה', exact: true });
    await expect(amount).toHaveValue('');

    // Watch for any write request (server action / offers endpoint) while invalid values are submitted.
    const writes: string[] = [];
    const onRequest = (r: Request) => {
      if (r.method() === 'GET') return;
      const h = r.headers();
      if (h['next-action'] || /offer/i.test(r.url())) writes.push(`${r.method()} ${r.url()}`);
    };
    page.on('request', onRequest);

    // 2. Invalid values: ≤ 0, fractions, non-numeric
    for (const v of INVALID_LOW) {
      await amount.fill('');
      await amount.pressSequentially(v);
      await submit.click();
      await expect(side.getByText(AMOUNT_ERR), `message for "${v}"`).toBeVisible();
      await expect(amount, `field marked invalid for "${v}"`).toHaveAttribute('aria-invalid', 'true');
    }

    // Above the maximum
    for (const v of INVALID_HIGH) {
      await amount.fill('');
      await amount.pressSequentially(v);
      await submit.click();
      await expect(side.getByText(MAX_ERR), `max message for "${v}"`).toBeVisible();
    }

    // Nothing was sent
    await expect(page.getByText(SENT)).toHaveCount(0);
    page.off('request', onRequest);
    expect(writes, 'no offer request is sent for invalid amounts').toEqual([]);

    // 3. Close the tender without sending a valid amount
    await amount.fill('');
    await page.getByRole('dialog').getByRole('button', { name: 'סגירה' }).click();
    await expect(page.getByRole('dialog')).toBeHidden();
  });
});
